<?php
namespace App\Http\Controllers;use App\Models\AudioCampaign;use App\Models\AudioSpot;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\View\View;
class AdminAudioAdvertisingController extends Controller{
 public function index():View{$this->guard();return view('admin.audio-advertising.index',['spots'=>AudioSpot::latest()->get(),'campaigns'=>AudioCampaign::with('spot')->withCount(['plays','plays as completed_plays_count'=>fn($q)=>$q->where('completed',true)])->latest()->get()]);}
 public function spot(Request $r):RedirectResponse{$this->guard();$d=$r->validate(['name'=>'required|string|max:140','advertiser'=>'nullable|string|max:140','audio'=>'nullable|file|mimes:mp3,m4a,mp4,wav,ogg|max:51200','audio_url'=>'nullable|url|max:2048','duration_seconds'=>'nullable|integer|min:1']);abort_if(!$r->hasFile('audio')&&!filled($d['audio_url']??null),422,'Informe o áudio.');if($r->hasFile('audio')){$f=$r->file('audio');$d['audio_path']=$f->store('audio-ads','public');$d['audio_mime']=$f->getMimeType()?:'audio/mpeg';}else{$d['audio_path']=$d['audio_url'];}unset($d['audio'],$d['audio_url']);AudioSpot::create($d+['is_active'=>true]);return back()->with('status','Spot cadastrado.');}
 public function campaign(Request $r):RedirectResponse{$this->guard();$d=$r->validate(['audio_spot_id'=>'required|exists:audio_spots,id','name'=>'required|string|max:140','status'=>'required|in:draft,active,paused,finished','starts_at'=>'nullable|date','ends_at'=>'nullable|date|after:starts_at','daily_starts_at'=>'nullable|date_format:H:i','daily_ends_at'=>'nullable|date_format:H:i|after:daily_starts_at','weekdays'=>'nullable|array','weekdays.*'=>'integer|min:0|max:6','max_plays'=>'nullable|integer|min:1','priority'=>'required|integer|min:0|max:100']);AudioCampaign::create($d);return back()->with('status','Campanha criada.');}
 private function guard():void{abort_unless(auth()->user()?->hasAnyRole(['Super Admin','Admin']),403);}
}
